import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';

const Navigation = () => {
  const navigate = useNavigate();
  const location = useLocation();

  const navItems = [
    { path: '/upload', label: 'Upload Bill' },
    { path: '/budget', label: 'Trip Budget' },
    { path: '/team-bills', label: 'Team Bills' },
    { path: '/profile', label: 'Profile' }
  ];

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  const isActive = (path) => location.pathname === path;

  return (
    <header
      style={{
        position: 'sticky',
        top: 0,
        zIndex: 1000,
        backgroundColor: '#ffffff',
        borderBottom: '1px solid #e5e7eb'
      }}
    >
      <nav
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '12px 20px',
          maxWidth: '1200px',
          margin: '0 auto'
        }}
      >
        <div
          onClick={() => navigate('/upload')}
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: '10px',
            cursor: 'pointer'
          }}
        >
          <div
            aria-hidden
            style={{
              width: 28,
              height: 28,
              borderRadius: 6,
              background: 'linear-gradient(135deg, var(--primary-color), var(--primary-hover))'
            }}
          ></div>
          <strong style={{ color: '#111827', letterSpacing: 0.2 }}>AI Expense Manager</strong>
        </div>

        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          {navItems.map((item) => (
            <button
              key={item.path}
              onClick={() => navigate(item.path)}
              style={{
                backgroundColor: isActive(item.path) ? 'var(--primary-color)' : '#ffffff',
                color: isActive(item.path) ? '#ffffff' : '#111827',
                border: isActive(item.path)
                  ? '1px solid var(--primary-hover)'
                  : '1px solid #e5e7eb',
                padding: '8px 14px',
                borderRadius: 8,
                cursor: 'pointer',
                fontSize: 14,
                fontWeight: 600,
                transition: 'all 0.2s ease',
              }}
              onMouseEnter={(e) => {
                if (!isActive(item.path)) {
                  e.currentTarget.style.borderColor = '#d1d5db';
                  e.currentTarget.style.backgroundColor = '#f9fafb';
                }
              }}
              onMouseLeave={(e) => {
                if (!isActive(item.path)) {
                  e.currentTarget.style.borderColor = '#e5e7eb';
                  e.currentTarget.style.backgroundColor = '#ffffff';
                }
              }}
            >
              {item.label}
            </button>
          ))}

          <div style={{ width: 1, height: 24, backgroundColor: '#e5e7eb', margin: '0 4px' }} />

          <button
            onClick={handleLogout}
            style={{
              backgroundColor: '#ffffff',
              color: '#b91c1c',
              border: '1px solid #fecaca',
              padding: '8px 14px',
              borderRadius: 8,
              cursor: 'pointer',
              fontSize: 14,
              fontWeight: 600,
              transition: 'all 0.2s ease'
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = '#fef2f2';
              e.currentTarget.style.borderColor = '#fca5a5';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = '#ffffff';
              e.currentTarget.style.borderColor = '#fecaca';
            }}
          >
            Logout
          </button>
        </div>
      </nav>
    </header>
  );
};

export default Navigation;
